  --ease: cubic-bezier(.2,.9,.2,1);
}

*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  background: radial-gradient(1200px 700px at 75% -10%, rgba(82,130,255,.22), transparent 55%),
              radial-gradient(900px 600px at 12% 12%, rgba(255,176,64,.16), transparent 52%),
              var(--bg);
  color: var(--text);
  letter-spacing: -0.01em;
}

a{color:inherit; text-decoration:none}
a:hover{text-decoration:none}
img{max-width:100%; display:block}

.container{
  width:min(var(--container), calc(100% - (var(--gutter) * 2)));
  margin-inline:auto;
}

.sr-only{
  position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0;
}

.skip-link{
  position:absolute; left:12px; top:12px;
  padding:10px 12px; border-radius:12px;
  background: var(--surface-2);
  border:1px solid var(--stroke);
  transform: translateY(-140%);
  transition: transform .18s var(--ease);
  z-index: 9999;
}
.skip-link:focus{transform: translateY(0)}

/* Topbar */
.topbar{
  position:sticky; top:0; z-index:1000;
  backdrop-filter: blur(14px);
  background: color-mix(in oklch, var(--bg) 78%, transparent);
  border-bottom: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
}
.topbar-inner{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:14px 0;}

.brand{
  display:flex; align-items:center; gap:10px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.brand-mark{
  width:28px; height:28px; border-radius:10px;
  background: conic-gradient(from 220deg, var(--blue), rgba(255,176,64,.95), rgba(255,255,255,.25), var(--blue));
  box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset, 0 10px 30px rgba(0,0,0,.35);
}
.brand span{font-size: 0.98rem}

.nav{
  display:flex; align-items:center; gap:18px;
}
.nav a{
  font-size: 0.95rem;
  color: color-mix(in oklch, var(--text) 86%, var(--muted));
  padding:10px 10px;
  border-radius: 12px;
}
.nav a:hover{background: color-mix(in oklch, var(--surface) 88%, transparent)}

.nav-actions{display:flex; align-items:center; gap:10px;}

.btn{
  display:inline-flex; align-items:center; justify-content:center; gap:10px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid color-mix(in oklch, var(--stroke) 80%, transparent);
  background: color-mix(in oklch, var(--surface) 92%, transparent);
  color: var(--text);
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
  transition: transform .16s var(--ease), background .16s var(--ease), border-color .16s var(--ease);
}
.btn:hover{transform: translateY(-1px); border-color: color-mix(in oklch, var(--stroke) 35%, var(--blue));}
.btn:active{transform: translateY(0)}
.btn.primary{
  background: linear-gradient(180deg, color-mix(in oklch, var(--blue) 70%, var(--surface)), color-mix(in oklch, var(--blue) 45%, var(--surface)));
  border-color: color-mix(in oklch, var(--blue) 70%, var(--stroke));
}
.btn.primary:hover{border-color: color-mix(in oklch, var(--blue) 92%, var(--stroke));}

.icon-btn{
  display:inline-flex; align-items:center; justify-content:center;
  width:42px; height:42px;
  border-radius: 14px;
  border: 1px solid color-mix(in oklch, var(--stroke) 80%, transparent);
  background: color-mix(in oklch, var(--surface) 92%, transparent);
  color: var(--text);
}

.mobile-toggle{display:none}

.lang{
  position: relative;
}
.menu{
  position:absolute; right:0; top:calc(100% + 10px);
  min-width: 220px;
  background: color-mix(in oklch, var(--surface) 92%, transparent);
  border: 1px solid color-mix(in oklch, var(--stroke) 75%, transparent);
  border-radius: 18px;
  box-shadow: var(--shadow);
  padding: 8px;
  display:none;
}
.menu[data-open="true"]{display:block}
.menu button{
  width:100%;
  text-align:left;
  padding: 10px 12px;
  border-radius: 14px;
  border:0;
  background: transparent;
  color: var(--text);
  cursor:pointer;
  font-size: 0.95rem;
}
.menu button:hover{background: color-mix(in oklch, var(--surface-2) 88%, transparent)}
.menu .meta{display:block; font-size: 0.8rem; color: var(--muted); margin-top:2px}

/* Sections */
.section{padding: 92px 0;}
.section.tight{padding: 70px 0;}
.section-title{
  display:flex; align-items:flex-end; justify-content:space-between; gap:18px;
  margin-bottom: 26px;
}
.kicker{
  color: var(--muted);
  font-size: var(--step--1);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.h2{
  font-size: var(--step-3);
  line-height: 1.02;
  letter-spacing: -0.03em;
  margin: 10px 0 0;
}
.lede{color: color-mix(in oklch, var(--muted) 80%, var(--text)); font-size: var(--step-0); max-width: 62ch; line-height:1.55}

/* Hero */
.hero{padding: 36px 0 42px;}
.hero-grid{display:grid; grid-template-columns: 1.05fr 0.95fr; gap: 26px; align-items: stretch;}

.hero-left{
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: linear-gradient(180deg, rgba(255,255,255,.03), rgba(255,255,255,0));
  overflow:hidden;
  box-shadow: var(--shadow);
  position: relative;
}
.hero-media{
  height: 520px;
  position: relative;
}
.hero-media::after{
  content:"";
  position:absolute; inset:0;
  background: linear-gradient(180deg, rgba(0,0,0,.05) 0%, rgba(0,0,0,.65) 65%, rgba(0,0,0,.9) 100%);
}
.hero-media img{
  width:100%; height:100%; object-fit: cover;
  filter: saturate(.85) contrast(1.05) brightness(.85);
}
.hero-card{
  position:absolute; left:22px; right:22px; bottom:18px;
  border-radius: 22px;
  border: 1px solid color-mix(in oklch, var(--stroke) 72%, transparent);
  background: color-mix(in oklch, var(--surface) 84%, transparent);
  backdrop-filter: blur(12px);
  padding: 18px 18px 16px;
}
.hero-title{font-size: var(--step-3); margin:0; line-height:1.05; letter-spacing:-0.03em}
.hero-copy{margin:10px 0 16px; color: color-mix(in oklch, var(--muted) 84%, var(--text)); line-height:1.55; font-size: var(--step-0)}
.hero-cta-row{display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap}
.hero-pills{display:flex; align-items:center; gap:10px; flex-wrap:wrap}
.pill{font-size: 0.85rem; padding: 7px 10px; border-radius: 999px; border: 1px solid color-mix(in oklch, var(--stroke) 75%, transparent); background: rgba(255,255,255,.04); color: var(--muted)}
.pill.blue{border-color: color-mix(in oklch, var(--blue) 55%, var(--stroke)); color: color-mix(in oklch, var(--blue) 85%, white)}
.pill.amber{border-color: color-mix(in oklch, var(--amber) 55%, var(--stroke)); color: color-mix(in oklch, var(--amber) 88%, white)}

.hero-right{
  display:flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 18px;
}
.hero-intro{
  padding: 18px 18px 16px;
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 86%, transparent);
  box-shadow: var(--shadow-soft);
}
.h1{
  font-size: var(--step-4);
  line-height: 0.98;
  letter-spacing: -0.045em;
  margin: 6px 0 10px;
}
.subhead{
  color: color-mix(in oklch, var(--muted) 78%, var(--text));
  font-size: var(--step-0);
  line-height: 1.6;
  margin: 0 0 14px;
}
.hero-actions{display:flex; gap:10px; flex-wrap:wrap}

.hero-controls{
  display:flex; align-items:center; justify-content:space-between; gap:12px;
  padding: 14px 14px;
  border-radius: 18px;
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 86%, transparent);
}
.dots{display:flex; gap:8px; align-items:center}
.dot{
  width:10px; height:10px; border-radius: 999px;
  background: color-mix(in oklch, var(--stroke) 80%, var(--surface-2));
  border: 1px solid color-mix(in oklch, var(--stroke) 55%, transparent);
  cursor:pointer;
}
.dot[aria-current="true"]{
  width: 26px;
  background: linear-gradient(90deg, var(--blue), color-mix(in oklch, var(--amber) 70%, var(--blue)));
  border-color: color-mix(in oklch, var(--blue) 70%, var(--stroke));
}

/* Region tabs */
.tabs{display:flex; gap:10px; flex-wrap:wrap}
.tab{
  padding: 10px 12px;
  border-radius: 999px;
  border: 1px solid color-mix(in oklch, var(--stroke) 78%, transparent);
  background: rgba(255,255,255,.03);
  color: color-mix(in oklch, var(--text) 88%, var(--muted));
  cursor:pointer;
  font-size: 0.95rem;
}
.tab[aria-selected="true"]{
  background: color-mix(in oklch, var(--surface-2) 86%, transparent);
  border-color: color-mix(in oklch, var(--blue) 60%, var(--stroke));
}

/* Carousels */
.carousel{
  position: relative;
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 84%, transparent);
  overflow:hidden;
  box-shadow: var(--shadow-soft);
}
.carousel-head{display:flex; align-items:center; justify-content:space-between; gap:10px; padding: 18px 18px 0;}
.carousel-title{margin:0; font-size: 1.1rem; color: color-mix(in oklch, var(--text) 88%, var(--muted))}
.carousel-controls{display:flex; gap:10px}
.carousel-controls button{cursor:pointer}

.track{
  display:flex;
  overflow:auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  gap: 14px;
  padding: 18px;
}
.track::-webkit-scrollbar{height: 10px}
.track::-webkit-scrollbar-thumb{background: color-mix(in oklch, var(--stroke) 70%, transparent); border-radius:999px}
.track::-webkit-scrollbar-track{background: transparent}

.card{
  scroll-snap-align: start;
  min-width: 320px;
  background: color-mix(in oklch, var(--surface-2) 86%, transparent);
  border: 1px solid color-mix(in oklch, var(--stroke) 70%, transparent);
  border-radius: var(--radius-lg);
  overflow:hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
}
.card .media{height: 210px; position:relative}
.card .media img{width:100%; height:100%; object-fit: cover; filter: saturate(.85) contrast(1.05) brightness(.85)}
.card .media::after{content:""; position:absolute; inset:0; background: linear-gradient(180deg, rgba(0,0,0,.0), rgba(0,0,0,.55));}
.card .body{padding: 14px 14px 16px}
.card h3{margin:0 0 8px; font-size: 1.05rem; letter-spacing:-0.02em}
.card p{margin:0 0 12px; color: color-mix(in oklch, var(--muted) 85%, var(--text)); line-height:1.55; font-size: 0.98rem}
.card .meta-row{display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap}

.quote{
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid color-mix(in oklch, var(--stroke) 75%, transparent);
  background: rgba(0,0,0,.22);
  color: color-mix(in oklch, var(--muted) 85%, var(--text));
  font-size: 0.95rem;
  line-height:1.55;
}

/* Work showcase cards (wider) */
.card.work{min-width: 420px}
.card.work .media{height: 240px}

/* Insights grid */
.grid{
  display:grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 16px;
}
.grid .insight{
  grid-column: span 4;
  border-radius: var(--radius-lg);
  border: 1px solid color-mix(in oklch, var(--stroke) 70%, transparent);
  background: color-mix(in oklch, var(--surface) 88%, transparent);
  overflow:hidden;
  box-shadow: 0 10px 30px rgba(0,0,0,.25);
  display:flex;
  flex-direction: column;
  min-height: 360px;
}
.insight .media{height: 190px; position:relative}
.insight .media img{width:100%; height:100%; object-fit: cover; filter: saturate(.85) contrast(1.05) brightness(.85)}
.insight .media::after{content:""; position:absolute; inset:0; background: linear-gradient(180deg, rgba(0,0,0,.0), rgba(0,0,0,.55));}
.insight .body{padding: 14px 14px 16px; display:flex; flex-direction:column; gap:10px; flex:1}
.tag{display:inline-flex; align-items:center; gap:8px; font-size:0.82rem; letter-spacing:0.08em; text-transform:uppercase; color: var(--muted)}
.tag::before{content:""; width:7px; height:7px; border-radius:999px; background: color-mix(in oklch, var(--blue) 70%, var(--stroke))}
.tag.amber::before{background: color-mix(in oklch, var(--amber) 80%, var(--stroke))}
.insight h3{margin:0; font-size: 1.05rem; letter-spacing:-0.02em; line-height:1.25}
.insight .spacer{flex:1}

/* CTA Banner */
.banner{
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 62%, transparent);
  background: radial-gradient(700px 280px at 20% 20%, rgba(82,130,255,.22), transparent 60%),
              radial-gradient(700px 280px at 90% 0%, rgba(255,176,64,.18), transparent 60%),
              color-mix(in oklch, var(--surface) 86%, transparent);
  box-shadow: var(--shadow);
  padding: 26px;
  display:flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 18px;
}
.banner h2{margin:0; font-size: var(--step-3); letter-spacing:-0.03em}
.banner p{margin:10px 0 0; color: color-mix(in oklch, var(--muted) 84%, var(--text)); max-width: 70ch; line-height:1.6}

/* How we work */
.split{display:grid; grid-template-columns: 1.1fr .9fr; gap: 18px; align-items: start;}
.panel{
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 86%, transparent);
  box-shadow: var(--shadow-soft);
  padding: 22px;
}
.panel h3{margin:0; font-size: var(--step-2); letter-spacing:-0.03em}
.panel p{margin:10px 0 14px; color: color-mix(in oklch, var(--muted) 84%, var(--text)); line-height:1.65}

.metrics{display:grid; grid-template-columns: 1fr 1fr; gap: 12px;}
.metric{
  border-radius: 18px;
  border: 1px solid color-mix(in oklch, var(--stroke) 70%, transparent);
  background: color-mix(in oklch, var(--surface-2) 86%, transparent);
  padding: 14px;
}
.metric b{display:block; font-size: 1.4rem}
.metric span{color: var(--muted); font-size: 0.9rem}

/* Principles */
.principles{display:grid; grid-template-columns: repeat(12, 1fr); gap: 16px;}
.principle{
  grid-column: span 6;
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 86%, transparent);
  box-shadow: var(--shadow-soft);
  padding: 18px;
}
.principle h3{margin:0 0 8px; letter-spacing:-0.02em}
.principle p{margin:0; color: color-mix(in oklch, var(--muted) 84%, var(--text)); line-height:1.6}

/* Footer */
.footer{
  border-top: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  padding: 48px 0 60px;
}
.footer-grid{display:grid; grid-template-columns: 1.2fr .8fr; gap: 18px;}
.footer-ctas{display:grid; gap:12px}
.footer-card{
  border-radius: var(--radius-xl);
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 86%, transparent);
  box-shadow: var(--shadow-soft);
  padding: 18px;
}
.footer-card p{margin:10px 0 14px; color: color-mix(in oklch, var(--muted) 84%, var(--text)); line-height:1.6}
.footer-links{display:flex; gap:14px; flex-wrap:wrap; align-items:center; justify-content:flex-end}
.footer-links a{color: var(--muted); padding:8px 10px; border-radius: 12px}
.footer-links a:hover{background: color-mix(in oklch, var(--surface) 88%, transparent); color: var(--text)}
.legal{margin-top: 18px; color: color-mix(in oklch, var(--muted) 86%, var(--text)); font-size: 0.92rem; line-height:1.6}
.legal a{color: var(--muted); text-decoration: underline; text-decoration-color: rgba(255,255,255,.22)}

/* Cookie banner */
.cookie{
  position: fixed;
  left: 18px;
  right: 18px;
  bottom: 18px;
  z-index: 2000;
  display:none;
}
.cookie[data-open="true"]{display:block}
.cookie-card{
  width:min(980px, 100%);
  margin: 0 auto;
  border-radius: 22px;
  border: 1px solid color-mix(in oklch, var(--stroke) 65%, transparent);
  background: color-mix(in oklch, var(--surface) 88%, transparent);
  box-shadow: var(--shadow);
  padding: 16px;
  display:flex;
  gap: 14px;
  align-items: flex-start;
  justify-content: space-between;
}
.cookie-card p{margin:0; color: color-mix(in oklch, var(--muted) 85%, var(--text)); line-height:1.55}
.cookie-actions{display:flex; gap:10px; flex-wrap:wrap; align-items:center; justify-content:flex-end}

/* Dialog */
dialog{
  border: 1px solid color-mix(in oklch, var(--stroke) 70%, transparent);
  border-radius: 22px;
  background: color-mix(in oklch, var(--surface) 92%, transparent);
  color: var(--text);
  box-shadow: var(--shadow);
  padding: 16px;
  width: min(720px, calc(100% - 32px));
}
dialog::backdrop{background: rgba(0,0,0,.65)}
.dialog-grid{display:grid; grid-template-columns: 1fr; gap: 10px;}
.dialog-grid label{display:flex; gap:10px; align-items:flex-start; padding: 10px 12px; border-radius: 16px; border: 1px solid color-mix(in oklch, var(--stroke) 75%, transparent); background: rgba(255,255,255,.03)}
.dialog-grid small{display:block; color: var(--muted); margin-top:2px; line-height:1.4}
.dialog-actions{display:flex; justify-content:flex-end; gap:10px; margin-top: 10px; flex-wrap:wrap}

/* Focus */
:focus-visible{outline: 2px solid color-mix(in oklch, var(--blue) 78%, white); outline-offset: 3px}

/* Responsive */
@media (max-width: 980px){
  .hero-grid{grid-template-columns: 1fr;}
  .hero-media{height: 440px}
  .split{grid-template-columns: 1fr;}
  .footer-grid{grid-template-columns: 1fr;}
  .footer-links{justify-content:flex-start}
}

@media (max-width: 860px){
  .nav{display:none}
  .mobile-toggle{display:inline-flex}
  .topbar-inner{padding: 12px 0}
}

@media (max-width: 700px){
  .section{padding: 72px 0}
  .hero{padding-top: 22px}
  .hero-media{height: 380px}
  .card{min-width: 78vw}
  .card.work{min-width: 86vw}
  .grid .insight{grid-column: span 12}
  .principle{grid-column: span 12}
  .banner{flex-direction: column; align-items:flex-start}
  .cookie-card{flex-direction: column; align-items: flex-start}
}
